/* SQL Study -> TonFLY/revisao | 004 | 2026-10-08
Execute no banco configurado em DB_NAME na Vercel (README: NossaRotina).
SSMS: selecione esse banco antes de executar o arquivo completo.
SQL Server 2012+. UTF-8. Reexecutavel: atualiza catalogo por IDs estaveis;
nao apaga dados nem altera questoes/labs/progresso existente.
Catalogo conferido: 43 modulos, 345 aulas, 347 materiais e 35 referencias.
Nao concede acesso Google, nao cria login Google e nao detecta permissao.
A API devera identificar o usuario autenticado e autorizar gravações por usuario;
user_id sozinho nao e mecanismo de autenticacao.
Nao inclui as 8 aulas complementares de outro curso neste catalogo.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb')
    THROW 50001, 'Selecione o banco da aplicacao (DB_NAME) antes de executar.', 1;
BEGIN TRY
BEGIN TRANSACTION;
IF SCHEMA_ID(N'courses') IS NULL EXEC(N'CREATE SCHEMA courses AUTHORIZATION dbo;');
IF OBJECT_ID(N'courses.Course',N'U') IS NULL
CREATE TABLE courses.Course (
 course_id varchar(60) NOT NULL PRIMARY KEY,
 title nvarchar(300) NOT NULL,
 folder_id varchar(100) NOT NULL,
 access_notice nvarchar(1500) NOT NULL,
 created_at datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 updated_at datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME()
);
IF OBJECT_ID(N'courses.Track',N'U') IS NULL
CREATE TABLE courses.Track (
 course_id varchar(60) NOT NULL,
 track_number int NOT NULL CHECK(track_number>0),
 title nvarchar(300) NOT NULL,
 PRIMARY KEY(course_id,track_number),
 FOREIGN KEY(course_id) REFERENCES courses.Course(course_id)
);
IF OBJECT_ID(N'courses.Module',N'U') IS NULL
CREATE TABLE courses.Module (
 module_id varchar(100) NOT NULL PRIMARY KEY,
 course_id varchar(60) NOT NULL,
 track_number int NOT NULL,
 module_number int NOT NULL CHECK(module_number>0),
 title nvarchar(500) NOT NULL,
 folder_id varchar(100) NOT NULL,
 UNIQUE(course_id,track_number,module_number),
 FOREIGN KEY(course_id,track_number) REFERENCES courses.Track(course_id,track_number)
);
IF OBJECT_ID(N'courses.Lesson',N'U') IS NULL
CREATE TABLE courses.Lesson (
 lesson_id varchar(100) NOT NULL PRIMARY KEY,
 module_id varchar(100) NOT NULL,
 sort_order int NOT NULL CHECK(sort_order>0),
 title nvarchar(1000) NOT NULL,
 drive_file_id varchar(100) NOT NULL UNIQUE,
 size_bytes bigint NOT NULL CHECK(size_bytes>=0),
 original_path nvarchar(2000) NOT NULL,
 UNIQUE(module_id,lesson_id),
 FOREIGN KEY(module_id) REFERENCES courses.Module(module_id)
);
IF OBJECT_ID(N'courses.Material',N'U') IS NULL
CREATE TABLE courses.Material (
 material_id varchar(100) NOT NULL PRIMARY KEY,
 module_id varchar(100) NOT NULL,
 lesson_id varchar(100) NULL,
 title nvarchar(1000) NOT NULL,
 drive_file_id varchar(100) NOT NULL UNIQUE,
 mime_type nvarchar(200) NOT NULL,
 extension nvarchar(20) NULL,
 size_bytes bigint NOT NULL CHECK(size_bytes>=0),
 original_path nvarchar(2000) NOT NULL,
 is_reference bit NOT NULL DEFAULT 0,
 -- RAR/ZIP continuam como anexos; nao ha extracao na aplicacao.
 FOREIGN KEY(module_id) REFERENCES courses.Module(module_id),
 FOREIGN KEY(module_id,lesson_id) REFERENCES courses.Lesson(module_id,lesson_id)
);
IF OBJECT_ID(N'courses.LessonProgress',N'U') IS NULL
CREATE TABLE courses.LessonProgress (
 user_id nvarchar(100) NOT NULL,
 lesson_id varchar(100) NOT NULL,
 completed bit NOT NULL DEFAULT 0,
 favorite bit NOT NULL DEFAULT 0,
 notes nvarchar(max) NULL,
 started_at datetime2(0) NULL,
 completed_at datetime2(0) NULL,
 last_opened_at datetime2(0) NULL,
 updated_at datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 PRIMARY KEY(user_id,lesson_id),
 FOREIGN KEY(lesson_id) REFERENCES courses.Lesson(lesson_id)
);
IF OBJECT_ID(N'courses.ModuleProgress',N'U') IS NULL
CREATE TABLE courses.ModuleProgress (
 user_id nvarchar(100) NOT NULL,
 module_id varchar(100) NOT NULL,
 completed bit NOT NULL DEFAULT 0,
 favorite bit NOT NULL DEFAULT 0,
 notes nvarchar(max) NULL,
 updated_at datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 PRIMARY KEY(user_id,module_id),
 FOREIGN KEY(module_id) REFERENCES courses.Module(module_id)
);
