SELECT DB_NAME() AS database_name;
SELECT (SELECT COUNT(*) FROM courses.Track WHERE course_id='sql-server-expert') AS tracks,
 (SELECT COUNT(*) FROM courses.Module WHERE course_id='sql-server-expert') AS modules,
 (SELECT COUNT(*) FROM courses.Lesson l JOIN courses.Module m ON m.module_id=l.module_id WHERE m.course_id='sql-server-expert') AS lessons,
 (SELECT COUNT(*) FROM courses.Material a JOIN courses.Module m ON m.module_id=a.module_id WHERE m.course_id='sql-server-expert' AND a.is_reference=0) AS materials,
 (SELECT COUNT(*) FROM courses.Material a JOIN courses.Module m ON m.module_id=a.module_id WHERE m.course_id='sql-server-expert' AND a.is_reference=1) AS [references];
